INSERT INTO food_reference_profiles (
    fdc_id, food_name, fiber_g_per_100g, calcium_mg_per_100g,
    iron_mg_per_100g, magnesium_mg_per_100g, potassium_mg_per_100g,
    sodium_mg_per_100g, vitamin_c_mg_per_100g, vitamin_d_mcg_per_100g,
    vitamin_b12_mcg_per_100g, folate_dfe_mcg_per_100g, omega3_g_per_100g,
    source_name, source_url, source_release
)
SELECT
    fdc_id, food_name, fiber_g, calcium_mg, iron_mg, magnesium_mg,
    potassium_mg, sodium_mg, vitamin_c_mg, vitamin_d_mcg,
    vitamin_b12_mcg, folate_dfe_mcg, omega3_g,
    'USDA FoodData Central — SR Legacy',
    'https://fdc.nal.usda.gov/download-datasets/',
    '2018-04'
FROM profile_data
WHERE 1
ON CONFLICT (fdc_id) DO UPDATE SET
    food_name = excluded.food_name,
    fiber_g_per_100g = excluded.fiber_g_per_100g,
    calcium_mg_per_100g = excluded.calcium_mg_per_100g,
    iron_mg_per_100g = excluded.iron_mg_per_100g,
    magnesium_mg_per_100g = excluded.magnesium_mg_per_100g,
    potassium_mg_per_100g = excluded.potassium_mg_per_100g,
    sodium_mg_per_100g = excluded.sodium_mg_per_100g,
    vitamin_c_mg_per_100g = excluded.vitamin_c_mg_per_100g,
    vitamin_d_mcg_per_100g = excluded.vitamin_d_mcg_per_100g,
    vitamin_b12_mcg_per_100g = excluded.vitamin_b12_mcg_per_100g,
    folate_dfe_mcg_per_100g = excluded.folate_dfe_mcg_per_100g,
    omega3_g_per_100g = excluded.omega3_g_per_100g,
    source_name = excluded.source_name,
    source_url = excluded.source_url,
    source_release = excluded.source_release;

WITH reference_data (
    nutrient_code, nutrient_name, unit, daily_reference, reference_type,
    comparison_mode, source_url, notes, sort_order
) AS (
    VALUES
        ('fiber_g', 'Клетчатка', 'г', 38, 'AI', 'minimum', 'https://www.nationalacademies.org/read/10872/chapter/13', 'Ориентир для мужчины 19–30 лет.', 1),
