)
INSERT INTO nutrient_reference_values (
    nutrient_code, nutrient_name, unit, daily_reference, reference_type,
    comparison_mode, source_url, notes, sort_order
)
SELECT * FROM reference_data
WHERE 1
ON CONFLICT (nutrient_code) DO UPDATE SET
    nutrient_name = excluded.nutrient_name,
    unit = excluded.unit,
    daily_reference = excluded.daily_reference,
    reference_type = excluded.reference_type,
    comparison_mode = excluded.comparison_mode,
    source_url = excluded.source_url,
    notes = excluded.notes,
    sort_order = excluded.sort_order;

